def solve(inputs: dict) -> float:
    X = inputs['start_value']
    for _ in range(inputs['steps']):
        X ^= (X << 13)
        X ^= (X >> 9)
        X ^= (X << 15)
        X &= 0xFFFFFFFF  # Ensure we stay within 32 bits
